import React, { useState } from 'react';
import { useForm } from 'react-hook-form';
import { zodResolver } from '@hookform/resolvers/zod';
import { z } from 'zod';

const schema = z.object({
  casa: z.string().min(1, 'Selecione uma casa'),
});

const GeneratedApp: React.FC = () => {
  const { register, handleSubmit, reset } = useForm<{ casa: string }>({ resolver: zodResolver(schema) });
  const [casas, setCasas] = useState(Array(9).fill(''));
  const [vez, setVez] = useState('X');
  const [vencedor, setVencedor] = useState<string | null>(null);

  const handleClick = (index: number) => {
    if (casas[index] || vencedor) return;
    const newCasas = [...casas];
    newCasas[index] = vez;
    setCasas(newCasas);
    setVez(vez === 'X' ? 'O' : 'X');
    checkWinner(newCasas);
  };

  const checkWinner = (newCasas: string[]) => {
    const lines = [
      [0, 1, 2], [3, 4, 5], [6, 7, 8], // linhas horizontais
      [0, 3, 6], [1, 4, 7], [2, 5, 8], // linhas verticais
      [0, 4, 8], [2, 4, 6] // diagonais
    ];

    for (let line of lines) {
      const [a, b, c] = line;
      if (newCasas[a] && newCasas[a] === newCasas[b] && newCasas[a] === newCasas[c]) {
        setVencedor(newCasas[a]);
        return;
      }
    }

    if (!newCasas.includes('')) {
      setVencedor('Empate');
    }
  };

  const resetGame = () => {
    setCasas(Array(9).fill(''));
    setVez('X');
    setVencedor(null);
    reset();
  };

  return (
    <div>
      <h1>Jogo da Velha</h1>
      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(3, 100px)', gap: '10px' }}>
        {casas.map((casa, index) => (
          <button key={index} onClick={() => handleClick(index)} disabled={vencedor !== null || casa !== ''}>
            {casa}
          </button>
        ))}
      </div>
      {vencedor && <p>{vencedor === 'Empate' ? 'Empate!' : `Vencedor: ${vencedor}`}</p>}
      <button onClick={resetGame}>Reiniciar</button>
    </div>
  );
};

export default GeneratedApp;
